import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.BrgDYx9l.js";var i=JSON.parse(`{"title":"肉鸽情报","description":"","frontmatter":{},"headers":[],"relativePath":"feature/dungeon.md","filePath":"feature/dungeon.md","lastUpdated":1794577071000}`),a={name:`feature/dungeon.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="肉鸽情报" tabindex="-1">肉鸽情报 <a class="header-anchor" href="#肉鸽情报" aria-label="Permalink to “肉鸽情报”">​</a></h1><p>收集展示肉鸽中常用的数据信息。</p><p><img src="/tarou-docs/assets/img/dungeon-img1.png" alt="alt text" width="321" height="654"></p><h2 id="节点信息" tabindex="-1">节点信息 <a class="header-anchor" href="#节点信息" aria-label="Permalink to “节点信息”">​</a></h2><p><img src="/tarou-docs/assets/img/dungeon-img2.png" alt="alt text" width="332" height="126"></p><p>把地图上所有节点根据类型分类统计数量，悬浮显示图标含义</p><h2 id="队伍信息" tabindex="-1">队伍信息 <a class="header-anchor" href="#队伍信息" aria-label="Permalink to “队伍信息”">​</a></h2><p><img src="/tarou-docs/assets/img/dungeon-img3.png" alt="alt text" width="304" height="109"></p><p>显示当前队伍血量信息，方便处理一些扣血事件，看血量是否达标</p><p>在游戏中调整角色位置后，队伍显示顺序会即时同步，各角色保留对应的血量信息。</p><h2 id="敌人信息" tabindex="-1">敌人信息 <a class="header-anchor" href="#敌人信息" aria-label="Permalink to “敌人信息”">​</a></h2><p><img src="/tarou-docs/assets/img/dungeon-img4.png" alt="alt text" width="321" height="60"></p><p>显示敌人血量，支持多目标，方便规划技能</p><h2 id="导本信息" tabindex="-1">导本信息 <a class="header-anchor" href="#导本信息" aria-label="Permalink to “导本信息”">​</a></h2><p><img src="/tarou-docs/assets/img/dungeon-img5.png" alt="alt text" width="318" height="314"></p><p>黄色表示标记的导本，会置顶显示，用于标记一些重要导本，通过点击切换标记状态。红框代表负面效果导本。筛选方式和游戏里一样。</p><p>导本获得、消耗与继承后的数量会随游戏响应同步更新，结算掉落中的导本也会计入当前肉鸽信息。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>未读取过详情的导本可能缺少说明，需要点击游戏中的对应导本更新数据。</p></div><h2 id="特殊事件" tabindex="-1">特殊事件 <a class="header-anchor" href="#特殊事件" aria-label="Permalink to “特殊事件”">​</a></h2><p>点击“特殊事件”查看当前地图上有背景图的特殊事件，包含图片、名称与事件说明。同一种事件合并展示，同名但类型不同的事件分别展示，地图发生变化时列表同步更新。</p><p>桌面与扩展使用独立窗口，移动端使用页内弹窗。说明支持换行，尚未填写的内容显示“说明待补充”；尚未读取地图或当前地图没有可展示的特殊事件时显示对应提示。</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};